{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (r) => new Fail(`line ${i + 1}: ${r}`)
    const num = (v, field, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) throw fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const word = t[0]
    if (word === 'bucket' || word === 'window' || word === 'route') {
      if (seenEvent) throw fail('declarations must come before the first event')
    }
    if (word === 'bucket') {
      if (t.length !== 5) throw fail('expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
      const capacity = num(t[2], 'capacity', 1)
      const refill = num(t[3], 'refill', 0)
      const per = num(t[4], 'per', 1)
      if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
    } else if (word === 'window') {
      if (t.length !== 4) throw fail('expected window <name> <limit> <span>')
      if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
      const limit = num(t[2], 'limit', 0)
      const span = num(t[3], 'span', 1)
      if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'window', name: t[1], limit, span })
    } else if (word === 'route') {
      if (t.length < 3) throw fail('expected route <prefix> <policy>...')
      if (!NAME.test(t[1])) throw fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) throw fail(`prefix ${t[1]} is routed twice`)
      const list = []
      for (const p of t.slice(2)) {
        if (!policies.has(p)) throw fail(`unknown policy ${p}`)
        list.push(policies.get(p))
      }
      routes.set(t[1], list)
    } else if (word === 'event') {
      if (t.length !== 3) throw fail('expected event <tick> <key>')
      const tick = num(t[1], 'tick', 0)
      if (!NAME.test(t[2])) throw fail(`invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) throw fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      seenEvent = true
      events.push({ tick, key: t[2], tickText: t[1] })
    } else {
      throw fail(`unknown directive ${word}`)
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map()
  const out = []
  const stats = new Map()
  for (const ev of events) {
    let best = null
    for (const p of routes.keys()) {
      if (ev.key.startsWith(p) && (best === null || p.length > best.length)) best = p
    }
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((pol) => {
        const id = pol.name + '\0' + ev.key
        let s = states.get(id)
        if (!s) {
          s = pol.kind === 'bucket' ? { units: pol.capacity * pol.per, last: ev.tick } : { ticks: [] }
          states.set(id, s)
        }
        if (pol.kind === 'bucket') {
          const cap = pol.capacity * pol.per
          s.units += pol.refill * (ev.tick - s.last)
          if (s.units > cap) s.units = cap
          s.last = ev.tick
        } else {
          const cut = ev.tick - pol.span
          s.ticks = s.ticks.filter((x) => x > cut)
        }
        return s
      })
      for (let i = 0; i < list.length; i++) {
        const pol = list[i]
        const ok = pol.kind === 'bucket' ? sts[i].units >= pol.per : BigInt(sts[i].ticks.length) < pol.limit
        if (!ok) { denied = pol.name; break }
      }
      if (denied === null) {
        list.forEach((pol, i) => {
          if (pol.kind === 'bucket') sts[i].units -= pol.per
          else sts[i].ticks.push(ev.tick)
        })
      }
    }
    const st = stats.get(ev.key) || { a: 0, d: 0 }
    if (denied === null) st.a++; else st.d++
    stats.set(ev.key, st)
    out.push(`${ev.tickText} ${ev.key} ${denied === null ? 'allow' : 'deny ' + denied}`)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let s = ''
  let ta = 0
  let td = 0
  for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    const { a, d } = stats.get(k)
    ta += a
    td += d
    s += `${k} allowed=${a} denied=${d}\n`
  }
  return s + `total allowed=${ta} denied=${td}\n`
}

try {
  const text = readFileSync(0, 'utf8')
  process.stdout.write(run(parse(text)))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
