{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
  // ok
} else if (mode === 'pack' && args.length === 2) {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else {
  fail(USAGE)
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depOrder = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depOrder.push(...w.slice(1))
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
for (const name of depOrder) if (!cost.has(name)) fail(`error: unknown task ${name}`)

const names = [...cost.keys()].sort()
const dl = new Map(names.map((t) => [t, [...(deps.get(t) || [])].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (t) => {
    state.set(t, 1)
    stack.push(t)
    for (const d of dl.get(t)) {
      if (state.get(d) === 1) {
        const c = stack.slice(stack.indexOf(d))
        c.push(d)
        fail('error: cycle: ' + c.join(' -> '), 3)
      }
      if (!state.has(d)) visit(d)
    }
    stack.pop()
    state.set(t, 2)
  }
  for (const t of names) if (!state.has(t)) visit(t)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const compute = (t) => {
  if (finish.has(t)) return
  let s = 0n
  let d = 0
  for (const x of dl.get(t)) {
    compute(x)
    if (finish.get(x) > s) s = finish.get(x)
    if (depth.get(x) + 1 > d) d = depth.get(x) + 1
  }
  start.set(t, s)
  finish.set(t, s + cost.get(t))
  depth.set(t, d)
}
for (const t of names) compute(t)
let total = 0n
for (const t of names) if (finish.get(t) > total) total = finish.get(t)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const t of names) (ws[depth.get(t)] ||= []).push(t)
  ws.forEach((w, k) => (out += `wave ${k}: ${w.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const t of names) out += `${t} start=${start.get(t)} finish=${finish.get(t)} depth=${depth.get(t)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const pr = (t) => {
    if (prio.has(t)) return prio.get(t)
    let best = 0n
    for (const u of names) if (dl.get(u).includes(t)) best = best > pr(u) ? best : pr(u)
    prio.set(t, best + cost.get(t))
    return prio.get(t)
  }
  // dependents map for efficiency
  const rev = new Map(names.map((t) => [t, []]))
  for (const t of names) for (const d of dl.get(t)) rev.get(d).push(t)
  const pr2 = (t) => {
    if (prio.has(t)) return prio.get(t)
    let best = 0n
    for (const u of rev.get(t)) { const v = pr2(u); if (v > best) best = v }
    prio.set(t, best + cost.get(t))
    return prio.get(t)
  }
  void pr
  for (const t of names) pr2(t)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  const done = new Map() // started tasks -> finish
  const free = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n
  let remaining = order.slice()
  let makespan = 0n
  for (;;) {
    for (;;) {
      let w = free.findIndex((f) => f <= t)
      if (w < 0) break
      const idx = remaining.findIndex((x) => dl.get(x).every((d) => done.has(d) && done.get(d) <= t))
      if (idx < 0) break
      const task = remaining.splice(idx, 1)[0]
      const f = t + cost.get(task)
      done.set(task, f)
      free[w] = f
      runs[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
