{"command":"cat package.json; cat > src/cli.js <<'EOF'
const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const ID = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }
const int = (s, field, least) => {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (events.length) fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!ID.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const capacity = int(f[2], 'capacity', 1)
        const refill = int(f[3], 'refill', 0)
        const per = int(f[4], 'per', 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per, st: new Map() })
      } else if (d === 'window') {
        if (f.length !== 4) fail('expected window <name> <limit> <span>')
        if (!ID.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const limit = int(f[2], 'limit', 0)
        const span = int(f[3], 'span', 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'window', limit, span, st: new Map() })
      } else if (d === 'route') {
        if (f.length < 3) fail('expected route <prefix> <policy>...')
        if (!ID.test(f[1])) fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
        const list = f.slice(2).map((n) => {
          if (!policies.has(n)) fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(f[1], list)
      } else if (d === 'event') {
        if (f.length !== 3) fail('expected event <tick> <key>')
        const tick = int(f[1], 'tick', 0)
        if (!ID.test(f[2])) fail(`invalid key ${f[2]}`)
        if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
        last = tick
        events.push({ tick, key: f[2] })
      } else {
        fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { routes, events }
}

// bucket state is held scaled by `per` so fractions stay exact
function advance(p, key, tick) {
  let s = p.st.get(key)
  if (p.kind === 'bucket') {
    if (!s) {
      s = { units: p.capacity * p.per, at: tick }
      p.st.set(key, s)
    } else {
      s.units += p.refill * (tick - s.at)
      const cap = p.capacity * p.per
      if (s.units > cap) s.units = cap
      s.at = tick
    }
  } else {
    if (!s) { s = { ticks: [] }; p.st.set(key, s) }
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
  return s
}
const allows = (p, s) => (p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.kind === 'bucket') s.units -= p.per
  else s.ticks.push(tick)
}

let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', (c) => { input += c })
process.stdin.on('end', () => {
  let out = ''
  try {
    const { routes, events } = parse(input)
    const counts = new Map()
    let ta = 0, td = 0
    for (const { tick, key } of events) {
      let best = null
      for (const pre of routes.keys()) {
        if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
      }
      let denier = null
      if (best !== null) {
        const list = routes.get(best)
        const states = list.map((p) => advance(p, key, tick))
        const i = list.findIndex((p, j) => !allows(p, states[j]))
        if (i >= 0) denier = list[i].name
        else list.forEach((p, j) => record(p, states[j], tick))
      }
      const c = counts.get(key) || { a: 0, d: 0 }
      counts.set(key, c)
      if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
      if (mode === 'replay') out += denier === null ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${denier}\n`
    }
    if (mode === 'summary') {
      for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
        out += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
      }
      out += `total allowed=${ta} denied=${td}\n`
    }
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exitCode = 2
    return
  }
  process.stdout.write(out)
})
EOF
