    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((i) => pad + toJson(i, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keysOut(n, path, out) {
  if (n.t === 'table') {
    for (const k of sorted(n.map)) {
      const c = n.map.get(k), p = path ? path + '.' + k : k
      out.push(p + ' ' + c.t); keysOut(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + `[${i}]`
      out.push(p + ' ' + c.t); keysOut(c, p, out)
    })
  }
}

function parseDoc(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root, curPath = []
  lines.forEach((line, i) => {
    try {
      const P = new Parser(line)
      P.ws()
      if (P.end()) return
      if (line[P.p] === '[') {
        const aot = line[P.p + 1] === '['
        P.p += aot ? 2 : 1
