      P.ws()
      if (P.end() || line[P.p] !== '=') fail('expected key = value')
      P.p++
      const v = P.value(curPath.concat(keys))
      P.ws()
      if (!P.end()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e instanceof Fail) e.message = `line ${i + 1}: ${e.message}`
