{"file_path":"src/scanner.js","content":"const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const RADIX = { x: isHex, b: (c) => c === '0' || c === '1', o: (c) => c !== undefined && c >= '0' && c <= '7' }

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  // digit run with single underscores between digits; returns count of chars consumed
  const run = (ok) => {
    let j = i
    if (!ok(cs[j])) return 0
    j++
    for (;;) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j - i
  }

  while (i < n) {
    const c = cs[i]
    const sl = line
    const sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      advN(2)
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { advN(2); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { advN(2); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(sl, sc, 'unterminated string')
      const val = cs.slice(i + 2, j).join('')
      advN(j + 1 - i)
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(val) })
      continue
    }
    if (isIdStart(c)) {
      let j = i
      while (isIdPart(cs[j])) j++
      const s = cs.slice(i, j).join('')
      advN(j - i)
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let j = i
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        const ok = RADIX[p.toLowerCase()]
        j = i + 2
        const save = i
        i = j
        j += run(ok)
        i = save
      } else {
        const save = i
        j += run(isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) {
          i = j + 1
          j = i + run(isDigit)
        }
        if (cs[j] === 'e' || cs[j] === 'E') {
          let k = j + 1
          if (cs[k] === '+' || cs[k] === '-') k++
          if (isDigit(cs[k])) {
            i = k
            j = k + run(isDigit)
          }
        }
        i = save
      }
      const bad = j === i + 2 && 'xXbBoO'.includes(cs[i + 1]) && c === '0' && !RADIX[cs[i + 1].toLowerCase()](cs[j - 0])
      let e = j
      while (isIdPart(cs[e])) e++
      const s = cs.slice(i, e).join('')
      if (e > j || bad) throw new ScanError(sl, sc, `invalid number ${s}`)
      advN(e - i)
      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      adv()
      let out = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '"') { adv(); break }
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch === '\\') {
          const bl = line
          const bc = col
          if (i + 1 >= n) throw new ScanError(sl, sc, 'unterminated string')
          const e = cs[i + 1]
          const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
          if (Object.hasOwn(simple, e)) { out += simple[e]; advN(2); continue }
          if (e === 'x' && isHex(cs[i + 2]) && isHex(cs[i + 3])) {
            out += String.fromCodePoint(parseInt(cs[i + 2] + cs[i + 3], 16))
            advN(4)
            continue
          }
          if (e === 'u' && cs[i + 2] === '{') {
            let j = i + 3
            while (isHex(cs[j])) j++
            if (j > i + 3 && cs[j] === '}') {
              const cp = parseInt(cs.slice(i + 3, j).join(''), 16)
              if (cp <= 0x10ffff) {
                out += String.fromCodePoint(cp)
                advN(j + 1 - i)
                continue
              }
            }
          }
          throw new ScanError(bl, bc, `invalid escape \\${e}`)
        }
        out += ch
        adv()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(out) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      advN(2)
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: c })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
"}

