import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { evaluateAll, depsOf, formatValue } from './eval.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
let cells
try {
  cells = parseSheet(input)
} catch (e) {
  if (e && e.sheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const c of cells) out += `${c.addr}=${formatValue(vals.get(c.addr))}\n`
} else {
  for (const c of cells) out += `${c.addr}:${depsOf(c).map((a) => ' ' + a).join('')}\n`
}
process.stdout.write(out)
"}

