  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j); i++; j++; bi = i; sj = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  flush(n, m)
  return out
}

