  let pos = 0, k = 0
  const stable = to => { if (to > pos) { regs.push({ t: 'stable', lines: base.slice(pos, to) }); pos = to } }
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) { re = Math.max(re, all[k].be); group.push(all[k++]) }
    stable(rs)
