export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0]))
    let active = 0
    let total = 0
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    history.push(votes)
    const round = { votes, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0) break
    const win = [...votes].find(([, v]) => v * 2 > active)
    if (win) { winner = win[0]; break }
    const min = Math.min(...votes.values())
    let tied = [...votes].filter(([, v]) => v === min).map(([c]) => c)
    for (const h of history) {
      if (tied.length === 1) break
      const m = Math.min(...tied.map((c) => h.get(c)))
      tied = tied.filter((c) => h.get(c) === m)
    }
    tied.sort()
    round.eliminated = tied[tied.length - 1]
    continuing.delete(round.eliminated)
  }
  return { rounds, winner }
}
