try {
  result = count(parse(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'rounds') {
  result.rounds.forEach((r, i) => {
    const items = [...r.votes].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
      .map(([c, v]) => `${c}=${v}`)
    out += `round ${i + 1}: ${items.join(' ')} exhausted=${r.exhausted}\n`
    if (r.eliminated) out += `eliminated ${r.eliminated}\n`
  })
} else out += `rounds ${result.rounds.length}\n`
out += result.winner ? `winner ${result.winner}\n` : 'no winner\n'
process.stdout.write(out)
