#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { count } from './count.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
let result
try {
  result = count(parse(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'rounds') {
  result.rounds.forEach((r, i) => {
    const items = [...r.votes].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
      .map(([c, v]) => `${c}=${v}`)
    out += `round ${i + 1}: ${items.join(' ')} exhausted=${r.exhausted}\n`
    if (r.eliminated) out += `eliminated ${r.eliminated}\n`
  })
} else out += `rounds ${result.rounds.length}\n`
out += result.winner ? `winner ${result.winner}\n` : 'no winner\n'
process.stdout.write(out)
