    const br = args[t ? 1 : 2]
    return br.k === 'range' ? ERR : evalNode(br)
  }
  if (name === 'ABS') {
    if (args.length !== 1) return ERR
    const vs = expandArg(args[0])
    const e = vs.find((v) => v.t === 'e')
    if (e) return e
    if (vs.length !== 1) return ERR
    const v = toNum(vs[0])
    return v.t === 'e' ? v : num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return NAME
  if (args.length < 1) return ERR
  const vs = args.flatMap(expandArg)
  const e = vs.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vs.filter((v) => v.t === 'n').length)
  const ns = []
  for (const v of vs) {
    const x = toNum(v)
    if (x.t === 'e') return x
    ns.push(x.v)
  }
