  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function collect(n, set) {
  switch (n.k) {
    case 'ref': if (n.a) set.add(key(n.a)); break
    case 'range': for (const k of rangeKeys(n.a, n.b)) set.add(k); break
    case 'paren': collect(n.e, set); break
    case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
