const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdc = (c) => isLetter(c) || isDigit(c) || c === '_'

function fail(line, col, message) {
  const e = new Error(message)
  e.scanError = true
  e.line = line
  e.col = col
  throw e
}

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const toks = []
  let i = 0, line = 1, col = 1
  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const at = (k) => cs[i + k]

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && at(1) === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && at(1) === '*') {
      const sl = line, sc = col
      let depth = 0
      do {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && at(1) === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && at(1) === '/') { adv(); adv(); depth-- }
        else adv()
      } while (depth > 0)
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => toks.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && at(1) === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) fail(sl, sc, 'unterminated string')
      adv()
      push('rawstring', JSON.stringify(v))
      continue
    }
    if (isLetter(c) || c === '_') {
      let s = ''
      while (i < n && isIdc(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const take = () => { s += adv() }
      const run = (pred) => {
        let any = false
        while (i < n) {
          if (pred(cs[i])) { take(); any = true }
          else if (cs[i] === '_' && any && pred(at(1))) take()
          else break
        }
        return any
      }
      let ok = true
      const p = at(1)
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        take(); take()
        const l = p.toLowerCase()
        const pred = l === 'x' ? isHex : l === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        ok = run(pred)
      } else {
        run(isDigit)
        if (at(0) === '.' && isDigit(at(1))) { take(); run(isDigit) }
        if (at(0) === 'e' || at(0) === 'E') {
          if (isDigit(at(1))) { take(); run(isDigit) }
          else if ((at(1) === '+' || at(1) === '-') && isDigit(at(2))) { take(); take(); run(isDigit) }
        }
      }
      if (!ok || isIdc(at(0))) {
        while (i < n && isIdc(cs[i])) take()
        fail(sl, sc, `invalid number ${s}`)
      }
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) fail(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '\n') fail(line, col, 'newline in string')
        if (d === '"') { adv(); break }
        if (d !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) fail(sl, sc, 'unterminated string')
        const e = cs[i]
        const bad = () => fail(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') { adv(); v += '\n' }
        else if (e === 't') { adv(); v += '\t' }
        else if (e === 'r') { adv(); v += '\r' }
        else if (e === '\\') { adv(); v += '\\' }
        else if (e === '"') { adv(); v += '"' }
        else if (e === '0') { adv(); v += '\0' }
        else if (e === 'x') {
          if (!isHex(at(1)) || !isHex(at(2))) bad()
          adv(); const h = adv() + adv()
          v += String.fromCharCode(parseInt(h, 16))
        } else if (e === 'u') {
          if (at(1) !== '{') bad()
          let k = 2, h = ''
          while (isHex(at(k))) h += at(k++)
          if (h === '' || at(k) !== '}' || parseInt(h, 16) > 0x10ffff) bad()
          for (let j = 0; j <= k; j++) adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else bad()
      }
      push('string', JSON.stringify(v))
      continue
    }
    const two = c + (at(1) ?? '')
    if (PUNCT2.includes(two)) { adv(); adv(); push('punct', two); continue }
    if (PUNCT1.includes(c)) { adv(); push('punct', c); continue }
    fail(sl, sc, `unexpected character ${c}`)
  }
  return toks
}
