        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name); cands.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      ballotSeen = true
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const names = t.slice(2), s = new Set()
      for (const name of names) {
        if (!seen.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (s.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        s.add(name)
      }
      ballots.push([BigInt(t[1]), names])
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  }
  if (cands === null) fail('error: no candidates')

  const cont = new Set(cands)
  const hist = new Map(cands.map(c => [c, []]))
  let out = '', rnd = 0, result = 'no winner'
  for (;;) {
    rnd++
    const cnt = new Map([...cont].map(c => [c, 0n]))
    let active = 0n, exhausted = 0n
    for (const [k, names] of ballots) {
      const f = names.find(x => cont.has(x))
      if (f === undefined) exhausted += k
      else { cnt.set(f, cnt.get(f) + k); active += k }
    }
    for (const c of cont) hist.get(c).push(cnt.get(c))
    const sorted = [...cont].sort((a, b) => cnt.get(a) > cnt.get(b) ? -1 : cnt.get(a) < cnt.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0)
    out += `round ${rnd}: ${sorted.map(c => `${c}=${cnt.get(c)}`).join(' ')} exhausted=${exhausted}\n`
    if (active === 0n) break
    const w = sorted.find(c => cnt.get(c) * 2n > active)
    if (w !== undefined) { result = `winner ${w}`; break }
    let set = sorted.filter(c => cnt.get(c) === cnt.get(sorted[sorted.length - 1]))
    for (;;) {
      if (set.length === 1) break
      let r = 0, found = false
      for (; r < rnd; r++) {
        const v = set.map(c => hist.get(c)[r])
        if (v.some(x => x !== v[0])) { found = true; break }
      }
      if (!found) break
      let min = set.map(c => hist.get(c)[r]).reduce((a, b) => b < a ? b : a)
      set = set.filter(c => hist.get(c)[r] === min)
    }
    const el = set.reduce((a, b) => (b > a ? b : a))
    cont.delete(el)
    out += `eliminated ${el}\n`
  }
  if (mode === 'tally') out = `rounds ${rnd}\n`
  process.stdout.write(out + result + '\n')
}
EOF
