try { text = readFileSync(0, 'utf8') } catch { text = '' }
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const costs = new Map()
const deps = new Map()
const used = []
lines.forEach((raw, i) => {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (costs.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    costs.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) used.push(x)
    deps.set(w[1], new Set([...(deps.get(w[1]) || []), ...w.slice(2)]))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of used) if (!costs.has(x)) fail(`error: unknown task ${x}`)

const names = [...costs.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (k) => {
    state.set(k, 1)
    stack.push(k)
    for (const d of dl.get(k)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(k, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map(), finish = new Map(), depth = new Map()
const calc = (k) => {
  if (finish.has(k)) return
  let s = 0n, d = 0
  for (const x of dl.get(k)) {
    calc(x)
    if (finish.get(x) > s) s = finish.get(x)
    if (depth.get(x) + 1 > d) d = depth.get(x) + 1
  }
  start.set(k, s); finish.set(k, s + costs.get(k)); depth.set(k, d)
}
names.forEach(calc)
let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

const out = []
if (mode === 'waves') {
  const maxD = names.reduce((m, k) => Math.max(m, depth.get(k)), -1)
  for (let d = 0; d <= maxD; d++) out.push(`wave ${d}: ${names.filter((k) => depth.get(k) === d).join(' ')}`)
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of dl.get(k)) rev.get(d).push(k)
  const pr = (k) => {
    if (prio.has(k)) return prio.get(k)
    let m = 0n
    for (const c of rev.get(k)) { const v = pr(c); if (v > m) m = v }
    prio.set(k, m + costs.get(k))
    return prio.get(k)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? cmp(a, b) : prio.get(a) > prio.get(b) ? -1 : 1))
  const free = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  const pending = new Set(order)
  let t = 0n, makespan = 0n
  while (pending.size) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      const k = order.find((x) => pending.has(x) && dl.get(x).every((d) => fin.has(d) && fin.get(d) <= t))
      if (k === undefined) break
      pending.delete(k)
      const f = t + costs.get(k)
      fin.set(k, f); free[w] = f
      ran[w].push(`${k}@${t}-${f}`)
      if (f > makespan) makespan = f
