    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (costs.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    costs.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) used.push(x)
    deps.set(w[1], new Set([...(deps.get(w[1]) || []), ...w.slice(2)]))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
