const names = [...costs.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (k) => {
    state.set(k, 1)
    stack.push(k)
    for (const d of dl.get(k)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
