const calc = (k) => {
  if (finish.has(k)) return
  let s = 0n, d = 0
  for (const x of dl.get(k)) {
    calc(x)
    if (finish.get(x) > s) s = finish.get(x)
    if (depth.get(x) + 1 > d) d = depth.get(x) + 1
  }
  start.set(k, s); finish.set(k, s + costs.get(k)); depth.set(k, d)
}
names.forEach(calc)
