  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? cmp(a, b) : prio.get(a) > prio.get(b) ? -1 : 1))
  const free = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  const pending = new Set(order)
  let t = 0n, makespan = 0n
  while (pending.size) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      const k = order.find((x) => pending.has(x) && dl.get(x).every((d) => fin.has(d) && fin.get(d) <= t))
