  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = at >= 0 ? a.slice(at + 1) : a
  const c = hp.indexOf(':', hp.lastIndexOf(']') + 1)
